"""
Blog System Implementation
=========================

This module provides a simple blog system with:
- Post model with title, content, author, and timestamp
- Comment model with content, author, and timestamp
- BlogManager with CRUD operations for posts and comments
- JSON persistence for data storage
"""

import json
import os
from datetime import datetime
from typing import List, Dict, Any


class Post:
    """Represents a blog post."""

    def __init__(self, title: str, content: str, author: str, post_id: str = None):
        self.id = post_id or str(int(datetime.now().timestamp()))
        self.title = title
        self.content = content
        self.author = author
        self.timestamp = datetime.now().isoformat()
        self.comments: List[Dict[str, Any]] = []

    def to_dict(self) -> Dict[str, Any]:
        """Convert post to dictionary for JSON serialization."""
        return {
            'id': self.id,
            'title': self.title,
            'content': self.content,
            'author': self.author,
            'timestamp': self.timestamp,
            'comments': self.comments
        }

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> 'Post':
        """Create post from dictionary."""
        post = cls(data['title'], data['content'], data['author'], data['id'])
        post.timestamp = data['timestamp']
        post.comments = data.get('comments', [])
        return post

    def add_comment(self, comment: Dict[str, Any]) -> None:
        """Add a comment to this post."""
        self.comments.append(comment)

    def __str__(self) -> str:
        return f"Post('{self.title}', '{self.author}', '{self.timestamp}')"


class Comment:
    """Represents a comment on a blog post."""

    def __init__(self, content: str, author: str, comment_id: str = None):
        self.id = comment_id or str(int(datetime.now().timestamp()))
        self.content = content
        self.author = author
        self.timestamp = datetime.now().isoformat()

    def to_dict(self) -> Dict[str, Any]:
        """Convert comment to dictionary for JSON serialization."""
        return {
            'id': self.id,
            'content': self.content,
            'author': self.author,
            'timestamp': self.timestamp
        }

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> 'Comment':
        """Create comment from dictionary."""
        comment = cls(data['content'], data['author'], data['id'])
        comment.timestamp = data['timestamp']
        return comment

    def __str__(self) -> str:
        return f"Comment('{self.content[:50]}...', '{self.author}', '{self.timestamp}')"


class BlogManager:
    """Manages blog posts and comments with CRUD operations and JSON persistence."""

    def __init__(self, data_file: str = 'blog_data.json'):
        self.data_file = data_file
        self.posts: Dict[str, Post] = {}
        self.load_data()

    def load_data(self) -> None:
        """Load blog data from JSON file."""
        if os.path.exists(self.data_file):
            try:
                with open(self.data_file, 'r') as f:
                    data = json.load(f)

                # Load posts
                for post_data in data.get('posts', []):
                    post = Post.from_dict(post_data)
                    self.posts[post.id] = post
            except (json.JSONDecodeError, KeyError) as e:
                print(f"Warning: Could not load data from {self.data_file}: {e}")
                self.posts = {}
        else:
            self.posts = {}

    def save_data(self) -> None:
        """Save blog data to JSON file."""
        data = {
            'posts': [post.to_dict() for post in self.posts.values()]
        }

        try:
            with open(self.data_file, 'w') as f:
                json.dump(data, f, indent=2)
        except Exception as e:
            print(f"Error saving data to {self.data_file}: {e}")

    def create_post(self, title: str, content: str, author: str) -> Post:
        """Create a new blog post."""
        post = Post(title, content, author)
        self.posts[post.id] = post
        self.save_data()
        return post

    def get_post(self, post_id: str) -> Post:
        """Get a post by ID."""
        return self.posts.get(post_id)

    def get_all_posts(self) -> List[Post]:
        """Get all posts."""
        return list(self.posts.values())

    def update_post(self, post_id: str, title: str = None, content: str = None, author: str = None) -> bool:
        """Update a post."""
        post = self.get_post(post_id)
        if not post:
            return False

        if title is not None:
            post.title = title
        if content is not None:
            post.content = content
        if author is not None:
            post.author = author

        self.save_data()
        return True

    def delete_post(self, post_id: str) -> bool:
        """Delete a post."""
        if post_id in self.posts:
            del self.posts[post_id]
            self.save_data()
            return True
        return False

    def add_comment(self, post_id: str, content: str, author: str) -> bool:
        """Add a comment to a post."""
        post = self.get_post(post_id)
        if not post:
            return False

        comment = Comment(content, author)
        post.add_comment(comment.to_dict())
        self.save_data()
        return True

    def get_comments(self, post_id: str) -> List[Dict[str, Any]]:
        """Get all comments for a post."""
        post = self.get_post(post_id)
        if not post:
            return []
        return post.comments


def main():
    """Example usage of the blog system."""
    print("Creating Blog System...")

    # Initialize blog manager
    blog = BlogManager()

    # Create some posts
    post1 = blog.create_post(
        title="First Blog Post",
        content="This is the content of my first blog post.",
        author="Alice"
    )

    post2 = blog.create_post(
        title="Second Blog Post",
        content="This is the content of my second blog post.",
        author="Bob"
    )

    print(f"Created posts: {len(blog.get_all_posts())}")

    # Add comments
    blog.add_comment(post1.id, "Great post!", "Charlie")
    blog.add_comment(post1.id, "Thanks for sharing.", "David")

    # Display posts with comments
    for post in blog.get_all_posts():
        print(f"\n{post.title} by {post.author}")
        print(f"Content: {post.content}")
        print(f"Comments: {len(post.comments)}")
        for comment in post.comments:
            print(f"  - {comment['content']} by {comment['author']} at {comment['timestamp']}")

    # Update a post
    blog.update_post(post2.id, content="Updated content for the second post.")

    # Delete a post
    blog.delete_post(post1.id)

    print(f"\nPosts after deletion: {len(blog.get_all_posts())}")


if __name__ == "__main__":
    main()
